import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

import static java.lang.Integer.min;
import static java.lang.Integer.max;

public class e1542easy {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);

        solve(s.nextInt(), s.nextInt());
    }


    public static void solve(int n, int mod) {
        ArrayList<long[]> inversions = new ArrayList<>();
        inversions.add(new long[]{1});

        long last[];
        long next[];
        for (int i = 1; i < n; i++) {
            last = inversions.get(i - 1);
            next = new long[i * (i + 1) / 2 + 1];

            int e;
            for (int j = 0; j < next.length; j++) {
                e = 0;
                for (int k = min(j, i); k >= 0; k--) {
                    if (j - k < last.length) {
                        e += last[j - k];
                        e = e % mod;
                    }
                }
                next[j] = e;
            }

            inversions.add(next);
        }

        for (int i = 0; i < n; i++) {
            //System.out.println(Arrays.toString(inversions.get(i)));
        }


        long perms[] = new long[n];
        perms[0] = 0;

        long c;
        long inv[];
        long m;
        for (int i = 1; i < n; i++) {
            c = (perms[i - 1] * (i + 1)) % mod;

            inv = inversions.get(i - 1);
            for (int j = 0; j < inv.length; j++) {
                for (int k = j + 2; k < inv.length; k++) {
                    m = min(k - j, i + 1);
                    c = (c + ((inv[j] * inv[k]) % mod) * ((m - 1) * (2 * i - (m - 2)) / 2)) % mod;
                }
            }

            perms[i] = c;
        }

        //System.out.println(Arrays.toString(perms));
        System.out.println(perms[n - 1]);
    }
}

